CREATE TRIGGER IF NOT EXISTS run_hour_count AFTER INSERT ON run_finished BEGIN INSERT INTO run_hour(hour,project_id,task,runner_id,harness,result,error_code,runs,wait_ms) VALUES(NEW.hour,NEW.project_id,NEW.task,NEW.runner_id,NEW.harness,NEW.result,NEW.error_code,1,NEW.wait_ms)
  ON CONFLICT(hour,project_id,task,runner_id,harness,result,error_code) DO UPDATE SET runs=runs+1,wait_ms=wait_ms+excluded.wait_ms; END;

CREATE TRIGGER IF NOT EXISTS run_hour_ready_mark AFTER UPDATE OF done ON projection_catchup WHEN NEW.projection='run_hour' AND OLD.done IS NOT NEW.done BEGIN UPDATE change_marks SET revision=revision+1 WHERE kind='runs'; END;

INSERT INTO projection_catchup(projection,phase,done) SELECT 'run_hour','runHours',
      NOT EXISTS(SELECT 1 FROM agent_runs WHERE status IN ('completed','failed') AND completed_at IS NOT NULL) ON CONFLICT DO NOTHING;

